cusolverStatus_t cusolverGetVersion(int * version) {
    // TraceCall("cusolverGetVersion");
    if (version == NULL) return CUSOLVER_STATUS_INVALID_VALUE;
    *version = CUSOLVER_VERSION;
    return CUSOLVER_STATUS_SUCCESS;
}

